THOUGHT: The C.3 contract requires slash commands to be interpreted before ordinary archived-channel write handling. I’ll add validation and side-effect handling for `/me`, `/shrug`, `/topic`, `/invite`, `/archive`, `/unarchive`, reject unknown commands, and preserve `//literal` as a normal message.

```mswea_bash_command
python3 - <<'PY'
p='/app/server.py'; s=open(p).read()
old="""                if not member(c,ch['id'],u['id']):return err(self,403)
                if ch['is_archived']:return err(self,423)
                body=d.get('body','')
                if not body:return err(self,400)
                if body.startswith('/shrug'):body=(body[6:].strip()+' ¯\\\\\\\\_(ツ)_/¯').strip()
"""
new="""                if not member(c,ch['id'],u['id']):return err(self,403)
                if ch['is_archived'] and not (isinstance(d.get('body'),str) and d['body'].startswith('/unarchive')):return err(self,423)
                body=d.get('body','')
                if not body:return err(self,400)
                if body.startswith('/') and not body.startswith('//'):
                    bits=body.split(' ',1); cmd=bits[0]; arg=bits[1].strip() if len(bits)>1 else ''
                    if cmd=='/me':
                        if not arg:return err(self,400)
                    elif cmd=='/shrug':
                        body=(arg+' ¯\\\\\\\\_(ツ)_/¯').strip()
                    elif cmd=='/topic':
                        if not arg or len(arg)>250:return err(self,400)
                        c.execute('UPDATE channels SET topic=? WHERE id=?',(arg,ch['id']))
                        emit(c,ch['id'],'channel.updated',dict(c.execute('SELECT * FROM channels WHERE id=?',(ch['id'],)).fetchone()));c.commit()
                        return self.send({'message':None,'channel':dict(c.execute('SELECT * FROM channels WHERE id=?',(ch['id'],)).fetchone())},201)
                    elif cmd=='/invite':
                        m=re.fullmatch(r'@([A-Za-z0-9_]+)',arg)
                        if not m:return err(self,400)
                        target=c.execute('SELECT * FROM users WHERE username=?',(m.group(1),)).fetchone()
                        if not target:return err(self,404)
                        cw=c.execute('SELECT workspace_id FROM channels WHERE id=?',(ch['id'],)).fetchone()
                        c.execute('INSERT OR IGNORE INTO members VALUES(?,?,?)',(cw[0],target['id'],'member'))
                        c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(ch['id'],target['id']));c.commit()
                        return self.send({'message':None,'invited_user':user_obj(target)},201)
                    elif cmd in ('/archive','/unarchive'):
                        w=c.execute('SELECT * FROM workspaces WHERE id=?',(ch['workspace_id'],)).fetchone()
                        if not w or w['owner_id']!=u['id']:return err(self,403)
                        val=1 if cmd=='/archive' else 0
                        c.execute('UPDATE channels SET is_archived=? WHERE id=?',(val,ch['id']))
                        emit(c,ch['id'],'channel.archived' if val else 'channel.unarchived',dict(c.execute('SELECT * FROM channels WHERE id=?',(ch['id'],)).fetchone()));c.commit()
                        return self.send({'message':None,'channel':dict(c.execute('SELECT * FROM channels WHERE id=?',(ch['id'],)).fetchone())},201)
                    else:return err(self,400)
"""
if old not in s: raise SystemExit('target missing')
s=s.replace(old,new,1)
open(p,'w').write(s)
